package uaic.security.stream;

import static org.junit.jupiter.api.Assertions.assertArrayEquals;

import org.junit.jupiter.api.Test;

class KeystreamTest {

    /** Emits 0, 1, 2, ... so the order of the generated bytes is visible. */
    private static Keystream countingKeystream() {
        int[] nextValue = { 0 };
        return () -> (byte) nextValue[0]++;
    }

    @Test
    void fillWritesConsecutiveBytes() {
        byte[] destination = new byte[4];
        countingKeystream().fill(destination);
        assertArrayEquals(new byte[] { 0, 1, 2, 3 }, destination);
    }

    @Test
    void fillContinuesWhereThePreviousCallStopped() {
        Keystream keystream = countingKeystream();
        byte[] first = new byte[2];
        byte[] second = new byte[3];
        keystream.fill(first);
        keystream.fill(second);
        assertArrayEquals(new byte[] { 2, 3, 4 }, second);
    }

    @Test
    void fillOfEmptyArrayConsumesNothing() {
        Keystream keystream = countingKeystream();
        keystream.fill(new byte[0]);
        byte[] destination = new byte[1];
        keystream.fill(destination);
        assertArrayEquals(new byte[] { 0 }, destination);
    }
}
